test("both mode begin append and overwritten scratch retain old owned record and output",[]{for(unsigned mode=0;mode<2;++mode){auto i=mode==0?held_named("analytic-chord-false-safe"):guard_named();run(i);const auto echo=record(mode,0),source=record(mode,1,0);ok(pp_sim_sphere_triangle_mesh_flight_begin(mode,2));equal(output(),source,"Valid begin published output");append(mode,i.triangles,0,1);equal(output(),source,"Valid append published output");std::fill_n(pp_sim_input_f64_ptr(),64,123.);equal(record(mode,0),echo,"Echo aliases caller scratch");equal(record(mode,1,0),source,"Original source aliases new staging");auto t=i.triangles[0];t[0]=99;append(mode,{t},0,1);write_input(i.query);ok(pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(i.query.size())));need(record(mode,1,1)[1]==99&&source[1]==37,"New owned commit mutated prior packet");}});
test("independent held and guard stages interleave without overwriting either committed record",[]{auto h=held_named();auto g=guard_named();run(h);const auto he=record(0,0);run(g);const auto ge=record(1,0);auto a=h.triangles[0],b=g.triangles[0];a[0]=511;b[0]=611;ok(pp_sim_sphere_triangle_mesh_flight_begin(0,1));append(0,{a},0,1);ok(pp_sim_sphere_triangle_mesh_flight_begin(1,1));append(1,{b},0,1);equal(record(0,0),he,"Other mode changed held committed echo");equal(record(1,0),ge,"Other mode changed guard committed echo");write_input(h.query);ok(pp_sim_sphere_triangle_mesh_flight_query(0,32));need(record(0,1,0)[1]==511,"Held stage overwritten by guard");equal(record(1,0),ge,"Held query replaced guard record");write_input(g.query);ok(pp_sim_sphere_triangle_mesh_flight_query(1,48));need(record(1,1,0)[1]==611&&record(0,1,0)[1]==511,"Guard commit erased held mode");});
test("invalid begin and final bad member of append chunk are atomic per mode",[]{for(unsigned mode=0;mode<2;++mode){auto i=mode==0?held_named():guard_named();run(i);const auto old=record(mode,1,0);for(auto n:{65u,std::numeric_limits<uint32_t>::max()}){rejected([&]{return pp_sim_sphere_triangle_mesh_flight_begin(mode,n);});}write_input(i.query);ok(pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(i.query.size())));equal(record(mode,1,0),old,"Bad begin erased staged original");for(double bad:{0.,-1.,1.5,9007199254740992.,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){ok(pp_sim_sphere_triangle_mesh_flight_begin(mode,3));auto t=i.triangles[0];t[0]=1;append(mode,{t},0,1);t[0]=2;std::copy(t.begin(),t.end(),pp_sim_input_f64_ptr());t[0]=bad;std::copy(t.begin(),t.end(),pp_sim_input_f64_ptr()+10);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_append(mode,20);});t[0]=2;auto u=t;u[0]=3;append(mode,{t,u},0,2);write_input(i.query);ok(pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(i.query.size())));need(record(mode,1,2)[1]==3,"Bad final append partially consumed chunk");}}});
test("all append chunk lengths incomplete overrun and nonfinite coordinates preserve recoverable stages",[]{for(unsigned mode=0;mode<2;++mode){auto i=mode==0?held_named():guard_named();run(i);ok(pp_sim_sphere_triangle_mesh_flight_begin(mode,2));for(auto n:{0u,1u,9u,11u,59u,61u,70u,std::numeric_limits<uint32_t>::max()}){rejected([&]{return pp_sim_sphere_triangle_mesh_flight_append(mode,n);});}write_input(i.query);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(i.query.size()));});append(mode,i.triangles,0,1);write_input(i.query);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(i.query.size()));});for(double v:{std::numeric_limits<double>::infinity(),-std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){auto t=i.triangles[0];t[9]=v;std::copy(t.begin(),t.end(),pp_sim_input_f64_ptr());rejected([&]{return pp_sim_sphere_triangle_mesh_flight_append(mode,10);});}auto t=i.triangles[0];t[0]=99;append(mode,{t},0,1);write_input(i.query);ok(pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(i.query.size())));rejected([&]{return pp_sim_sphere_triangle_mesh_flight_append(mode,10);});}});
test("whole query finite count ID integer static and reserved checks precede all mutation",[]{for(unsigned mode=0;mode<2;++mode){auto i=mode==0?held_named():guard_named();run(i);const auto old=record(mode,0);for(auto n:{0u,31u,33u,47u,49u,std::numeric_limits<uint32_t>::max()}){write_input(i.query);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,n);});}for(unsigned at=0;at<i.query.size();++at){for(double bad:{std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){auto q=i.query;q[at]=bad;write_input(q);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(q.size()));});}}for(double id:{0.,-1.,.5,9007199254740992.}){auto q=i.query;q[0]=id;write_input(q);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(q.size()));});}const unsigned base=mode==0?16:32;for(unsigned j:{0u,1u,2u,3u,8u,9u,10u,11u,12u}){for(double bad:{-1.,.5,4294967296.}){auto q=i.query;q[base+j]=bad;write_input(q);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(q.size()));});}}for(unsigned at=mode==0?29:46;at<i.query.size();++at){for(double bad:{1.,-0.}){auto q=i.query;q[at]=bad;write_input(q);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(q.size()));});}}if(mode==1){for(double flag:{-1.,.5,2.}){auto q=i.query;q[1]=flag;write_input(q);rejected([&]{return pp_sim_sphere_triangle_mesh_flight_query(mode,48);});}}equal(record(mode,0),old,"Host rejection changed old committed echo");write_input(i.query);ok(pp_sim_sphere_triangle_mesh_flight_query(mode,uint32_t(i.query.size())));}});
test("finite invalid settings reach model and negativezero integers keep original only",[]{for(unsigned mode=0;mode<2;++mode){auto i=mode==0?held_named():guard_named();const unsigned base=mode==0?16:32;for(unsigned j:{0u,1u,2u,3u,8u,9u,11u,12u}){for(double v:{0.,4294967295.}){auto bad=i;bad.query[base+j]=v;const auto p=run(bad);need(p[1]==(mode==0?4:2)&&p[4]==0,"Invalid uint32 model setting became host rejection/success");verify_packets(bad,p);}}auto zero=i;zero.query[base+10]=-0.;if(mode==1){zero.query[1]=-0.;}const auto p=run(zero);verify_packets(zero,p);need(std::signbit(record(mode,0)[base+10])&&!std::signbit(record(mode,2)[base+10]),"Integer negativezero echo/canonical snapshot mixed");if(mode==1){need(std::signbit(record(1,0)[1])&&!std::signbit(record(1,5)[1])&&!std::signbit(record(1,2)[1]),"Static negativezero did not canonicalize false");}}});
